import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";
import { predictionAPI } from "../services/api";

export default function HistoryPage() {
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    predictionAPI.history()
      .then(({ data }) => setRecords(data.records))
      .catch(() => setError("Failed to load history"))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="loading-screen"><span className="spinner"></span></div>;

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <h1 style={{ fontSize: "1.5rem", fontWeight: 700, marginBottom: "1.5rem" }}>Assessment History</h1>
        {error && <div className="alert alert-error">{error}</div>}
        <div className="card">
          {records.length === 0 ? (
            <p style={{ color: "var(--text-muted)" }}>No assessments yet.</p>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>Date</th><th>Result</th><th>Risk %</th><th>Age</th><th>BMI</th>
                    <th>Glucose</th><th>Smoking</th>
                  </tr>
                </thead>
                <tbody>
                  {records.map((r) => (
                    <tr key={r._id}>
                      <td>{new Date(r.createdAt).toLocaleDateString()}</td>
                      <td>
                        <span className={`badge ${r.predictionResult === "Likely" ? "badge-danger" : "badge-success"}`}>
                          {r.predictionResult}
                        </span>
                      </td>
                      <td>{r.riskProbability}%</td>
                      <td>{r.age}</td>
                      <td>{r.bmi}</td>
                      <td>{r.avgGlucoseLevel}</td>
                      <td style={{ textTransform: "capitalize" }}>{r.smokingStatus}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
